css:
.loader {
  position: relative;
  width: 34px;
  height: 52px;
}
.loader::before {
  content: "";
  position: absolute;
  top: 2px;
  left: 50%;
  width: 30px;
  height: 30px;
  margin-left: -15px;
  border-radius: 50%;
  background: #6366f1;
  box-shadow: 0 0 12px 2px #6366f1;
  animation: glow 1.2s ease-in-out infinite;
}
.loader i {
  position: absolute;
  top: 31px;
  left: 50%;
  width: 14px;
  height: 13px;
  margin-left: -7px;
  border-radius: 0 0 3px 3px;
  background: #4338ca;
}
.loader i::before {
  content: "";
  position: absolute;
  top: 3px;
  left: 1px;
  right: 1px;
  height: 1px;
  background: #312e81;
  box-shadow: 0 4px 0 #312e81, 0 8px 0 #312e81;
}
@keyframes glow {
  0%, 100% { opacity: 1; }
  45% { opacity: 0.32; }
  55% { opacity: 0.9; }
}
